function fieldInput(string $module,string $key,array $definition,mixed $value,array $entities,JsonRepository $repo):void{$label=$definition[0];$type=$definition[1];$required=$definition[2]??false;$name='record['.$key.']';$requiredAttr=$required?' required':'';if(str_starts_with($type,'relation:')||str_starts_with($type,'relation-many:')){$many=str_starts_with($type,'relation-many:');$target=substr($type,$many?14:9);$rows=scopedRows($target,$repo);$selectedIds=$many?(array)$value:[$value];foreach($selectedIds as $selectedId){if($selectedId!==''&&($linkedRow=$repo->find($target,(string)$selectedId))&&canAccessRecord($target,$linkedRow,$repo)&&!recordIsActive($linkedRow))$rows[]=$linkedRow;}if($target==='supervisores'&&$module==='estagiarios'&&currentUser()['perfil']==='Supervisor')$rows=array_values(array_filter($rows,fn($r)=>$r['id']===(currentUser()['supervisor_id']??'')));echo '<label class="field"><span>'.e($label).($required?' <i>*</i>':'').'</span><select name="'.e($name).($many?'[]':'').'"'.($many?' multiple size="4"':'').$requiredAttr.'>';if(!$many)echo '<option value="">Seleccione</option>';foreach($rows as $row){$selected=$many?in_array($row['id'],is_array($value)?$value:[],true):(($value??'')===$row['id']);$display=$row['nome']??$row['titulo']??$row['numero']??$row['id'];echo '<option value="'.e($row['id']).'"'.($selected?' selected':'').'>'.e($row['id'].' · '.$display).'</option>';}echo '</select></label>';return;}if(str_starts_with($type,'options:')){$options=explode('|',substr($type,8));echo '<label class="field"><span>'.e($label).($required?' <i>*</i>':'').'</span><select name="'.e($name).'"'.$requiredAttr.'>';foreach($options as $option)echo '<option value="'.e($option).'"'.(($value??'')===$option?' selected':'').'>'.e($option).'</option>';echo '</select></label>';return;}if($key==='password'&&$module==='utilizadores'&&$action==='editar')echo '<label class="field"><span>'.e($label).'</span><input type="password" name="record[password]" autocomplete="ne