function renderPermissionsMatrix(?array $record):void{$modules=require __DIR__.'/config/entities.php';unset($modules['utilizadores']);$modules+=['dashboard'=>['title'=>'Painel'],'relatorios'=>['title'=>'Relatórios'],'configuracoes'=>['title'=>'Configurações']];$defaults=rolePermissions($record['perfil']??'Gestor');$selected=$record['permissions']??$defaults;?><fieldset class="permission-matrix" data-defaults="<?=e(json_encode(['Administrador'=>rolePermissions('Administrador'),'Gestor'=>rolePermissions('Gestor'),'Funcionário'=>rolePermissions('Funcionário'),'Supervisor'=>rolePermissions('Supervisor')],JSON_UNESCAPED_UNICODE))?>"><legend>Permissões deste utilizador</legend><p>Marque o que esta conta pode consultar ou alterar. Os registos não são eliminados; altere a situação para Inactivo.</p><div class="permission-grid"><div class="permission-row permission-heading"><span>Módulo</span><span>Ver</span><span>Criar</span><span>Editar</span></div><?php foreach($modules as $key=>$module):$label=$module['title']??ucfirst($key);?><div class="permission-row" data-module="<?=e($key)?>"><span><?=e($label)?></span><?php foreach(['view','create','edit'] as $action):$locked=($key==='supervisores'&&$action!=='view')||$key==='utilizadores';$checked=in_array($action,(array)($selected[$key]??[]),true);?><label><input type="checkbox" name="record[permissions][<?=$key?>][]" value="<?=$action?>"<?=($checked&&!$locked?' checked':'')?><?=($locked?' disabled':'')?>><span class="sr-only"><?=e($action)?></span></label><?php endforeach?></div><?php endforeach?></div><input type="hidden" name="record[permissions_present]" value="1"></fieldset><?php }
function humanValue(string $key,mixed $value,JsonRepository $repo):string{if($key==='ativo')return $value===false?'Inactivo':'Activo';if(is_array($value)){$labels=[];foreach($value as $id)$labels[]=humanValue($key,$id,$repo);return implode(', ',$labels);}foreach(['clientes'=>'cliente_id','supervisores'=>'supervisor_id','processos'=>'processo_id','vagas'=>'vaga_ids'] as $target=>$fk){if($key===$fk){$row=$repo->find($target,(string)$value);return $row?($row['id'].' · '.($row['nome']??$row['titulo']??$row['numero']??'')):(string)$value;}}return (string)$value;}
