function moduleUrl(string $module,string $action='index',string $id=''):string{return '/pages/'.$module.'/'.$action.'.php'.($id!==''?'?id='.urlencode($id):'');}
function saveRecord(string $module,array $meta,JsonRepository $repo,string $action):never{verifyCsrf();$input=$_POST['record']??[];if(!is_array($input))$input=[];$id=$action==='editar'?(string)($_POST['id']??''):'';$old=$id!==''?$repo->find($module,$id):null;if($id!==''&&(!$old||!canAccessRecord($module,$old,$repo,'edit'))){flash('error','Registo não encontrado ou sem acesso.');redirect(moduleUrl($module));}$deadlineLocked=$module==='prazos'&&$old&&deadlineIsLocked($old);$record=[];foreach($meta['fields'] as $key=>$def){if(in_array($key,['ativo','active'],true)){$record[$key]=$old[$key]??($key==='active'?'Activo':true);continue;}$raw=$input[$key]??($old[$key]??'');if($module==='prazos'&&$key==='estado')$raw=$old['estado']??'Dentro do prazo';if($deadlineLocked&&!in_array($key,['data_entrega','nota_atraso'],true))$raw=$old[$key]??'';if($deadlineLocked&&$key==='data_entrega'&&!empty($old['data_entrega']))$raw=$old['data_entrega'];$type=$def[1];if(str_starts_with($type,'relation-many:')){$target=substr($type,14);$record[$key]=array_values(array_filter((array)$raw,fn($v)=>($linked=$repo->find($target,(string)$v))!==null&&canAccessRecord($target,$linked,$repo)));}elseif(str_starts_with($type,'relation:')){$target=substr($type,9);$record[$key]=(string)$raw;if($module==='estagiarios'&&$key==='supervisor_id'&&currentUser()['perfil']==='Supervisor')$record[$key]=currentUser()['supervisor_id']??'';if($record[$key]!==''&&(($linked=$repo->find($target,$record[$key]))===null||!canAccessRecord($target,$linked,$repo))){flash('error','Seleccione uma associação válida para «'.$def[0].'».');redirect(moduleUrl($module,$action,$id));}}elseif($key==='password'){if(trim((string)$raw)!=='')$record[$key]=password_hash((string)$raw,PASSWORD_DEFAULT);elseif($old)$record[$key]=$old[$key]??'';else $record[$key]='';}else $record[$key]=trim((string)$raw);if(($def[2]??false)&&$record[$key]===''){flash('error','O campo «'.$def[0].'» é obrigatório.');redirect(moduleUrl($module,$action,$id));}if(str_starts_with($type,'options:')&&!in_array($record[$key],explode('|',substr($type,8)),true)){flash('error','Opção inválida no campo «'.$def[0].'».');redirect(moduleUrl($module,$action,$id));}if($type==='email'&&!filter_var($record[$key],FILTER_VALIDATE_EMAIL)){flash('error','Indique um endereço de e-mail válido.');redirect(moduleUrl($module,$action,$id));}if($type==='date'&&$record[$key]!==''&&(!DateTimeImmutable::createFromFormat('!Y-m-d',$record[$key])||DateTimeImmutable::createFromFormat('!Y-m-d',$record[$key])->format('Y-m-d')!==$record[$key])){flash('error','Indique uma data válida no campo «'.$def[0].'».');redirect(moduleUrl($module,$action,$id));}}
if($module==='utilizadores'){$allowedProfiles=['Administrador','Gestor','Funcionário','Supervisor'];if(!in_array($record['perfil']??'', $allowedProfiles,true)){flash('error','Tipo de utilizador inválido.');redirect(moduleUrl($module,$action,$id));}if(($record['perfil']??'')==='Supervisor'){if(empty($record['supervisor_id'])||!$repo->find('supervisores',$record['supervisor_id'])){flash('error','Associe a conta a um registo de supervisor válido.');redirect(moduleUrl($module,$action,$id));}}else $record['supervisor_id']='';if(currentUser()['id']===$id&&($old['perfil']??'')==='Administrador'&&$record['perfil']!=='Administrador'){flash('error','Não pode retirar o perfil Administrador da sua própria conta.');redirect(moduleUrl($module,'editar',$id));}$posted=$input['permissions']??[];$permissions=[];$permissionModules=array_merge(array_keys(require __DIR__.'/config/entities.php'),['dashboard','relatorios','configuracoes']);foreach($permissionModules as $permissionModule){if($permissionModule==='utilizadores')continue;$allowed=['view','create','edit'];if($permissionModule==='supervisores')$allowed=['view'];$permissions[$permissionModule]=array_values(array_intersect($allowed,(array)($posted[$permissionModule]??[])));}$record['permissions']=$permissions;if(empty($record['password'])){flash('error','Defina uma palavra-passe para o utilizador.');redirect(moduleUrl($module,$action,$id));}}
if(isset($record['email']))foreach($repo->all($module) as $other)if(strtolower($other['email']??'')===strtolower($record['email'])&&($other['id']??'')!==$id){flash('error','Este e-mail já está registado.');redirect(moduleUrl($module,$action,$id));}if($module==='prazos'){if(!empty($record['data_entrega'])&&$record['data_entrega']>(new DateTimeImmutable('today'))->format('Y-m-d')){flash('error','A data de entrega não pode ser futura.');redirect(moduleUrl($module,$action,$id));}$record['estado']=deadlineStatus($record);if((($record['estado']??'')==='Entregue fora do prazo'||($record['estado']??'')==='Vencido')&&trim((string)($record['nota_atraso']??''))===''){flash('error','Registe a nota com o motivo do atraso.');redirect(moduleUrl($module,$action,$id));}}if($old)$record['id']=$id;if($module!=='utilizadores')$record['_owner_id']=$old['_owner_id']??currentUser()['id'];try{$saved=$repo->save($module,$record,$id?:null);$repo->log(currentUser()['nome'],$id?'Actualizou':'Criou',$meta['singular'],$saved['id']);if($module==='utilizadores'&&$id===currentUser()['id']){unset($saved['password']);$_SESSION['user']=$saved;}flash('success',$meta['singular'].' '.($id?'actualizado':'criado').' com sucesso ('.$saved['id'].').');redirect(moduleUrl($module));}catch(Throwable $e){flash('error','Não foi possível guardar o registo: '.$e->getMessage());redirect(moduleUrl($module,$action,$id));}}
function deactivateRecord(string $module,array $meta,JsonRepository $repo):never{verifyCsrf();$id=(string)($_POST['id']??'');$record=$repo->find($module,$id);if(!$record||!can($module,'edit')||!canAccessRecord($module,$record,$repo,'edit')){http_response_code(403);exit('Sem permissão para alterar este registo.');}if($module==='utilizadores'&&$id===currentUser()['id']){flash('error','Não pode inativar a sua própria conta.');redirect(moduleUrl($module));}if($module==='utilizadores'&&($record['perfil']??'')==='Administrador'&&recordIsActive($record)){$activeAdmins=array_filter($repo->all('utilizadores'),fn($u)=>($u['perfil']??'')==='Administrador'&&recordIsActive($u));if(count($activeAdmins)<=1){flash('error','O sistema deve manter pelo menos um Administrador activo.');redirect(moduleUrl($module));}}$active=recordIsActive($record);$field=$module==='utilizadores'?'active':'ativo';$record[$field]=$active?($module==='utilizadores'?'Inactivo':false):($module==='utilizadores'?'Activo':true);try{$repo->save($module,$record,$id);$repo->log(currentUser()['nome'],$active?'Inactivou':'Reactivou',$meta['singular'],$id);flash('success',$meta['singular'].' '.($active?'inactivado':'reactivado').' com sucesso.');redirect(moduleUrl($module).'?situacao='.($active?'inativos':'ativos'));}catch(Throwable $e){flash('error','Não foi possível alterar a situação: '.$e->getMessage());redirect(moduleUrl($module));}}
