  $id=(string)($_GET['id']??'');$record=$action==='editar'?$repo->find($module,$id):null;if($record&&!canAccessRecord($module,$record,$repo,'edit'))$record=null;if($record&&!recordIsActive($record)&&!in_array($_GET['situacao']??'', ['inativos','todos'],true))$record=null;if($action==='editar'&&!$record){flash('error','Registo não encontrado.');redirect(moduleUrl($module));}
  ?>
  <div class="page-heading"><div><h1><?=e($titlePage)?></h1><p>Preencha os dados do registo.</p></div><a class="btn btn-light" href="<?=moduleUrl($module)?>"><?=iconSvg('chevron','button-svg back-svg')?> Voltar</a></div><div class="panel"><form method="post"><?php csrfInput();if($record):?><input type="hidden" name="id" value="<?=e($id)?>"><?php endif?><div class="form-grid"><?php foreach($meta['fields'] as $key=>$def){$default='';if($key==='estado')$default=match($module){'processos'=>'Pendente','estagiarios'=>'Em andamento','vagas'=>'Aberta',default=>'Dentro do prazo'};$deadlineLocked=$module==='prazos'&&$record&&deadlineIsLocked($record);if(in_array($key,['ativo','active'],true)){$display=recordIsActive($record??[])?'Activo':'Inactivo';?><label class="field"><span><?=e($def[0])?></span><input value="<?=e($display)?>" readonly></label><?php }elseif($module==='prazos'&&$key==='estado'){$display=$record?deadlineStatus($record):'Dentro do prazo';?><label class="field"><span><?=e($def[0])?></span><input value="<?=e($display)?>" readonly></label><?php }elseif($deadlineLocked&&(!in_array($key,['data_entrega','nota_atraso'],true)||($key==='data_entrega'&&!empty($record['data_entrega'])))){$display=humanValue($key,$record[$key]??'',$repo);?><label class="field"><span><?=e($def[0])?></span><input value="<?=e($display?:'—')?>" readonly></label><?php }else fieldInput($module,$key,$def,$record[$key]??$default,$entities,$repo);}?></div><?php if($module==='utilizadores'&&currentUser()['perfil']==='Administrador')renderPermissionsMatrix($record);?><div class="form-actions"><a class="btn btn-light" href="<?=moduleUrl($module)?>">Cancelar</a><button class="btn btn-primary">Guardar</button></div></form></div>
  <?php
 }else{
  $id=(string)($_GET['id']??'');$record=$repo->find($module,$id);if($record&&!canAccessRecord($module,$record,$repo))$record=null;if($record&&!recordIsActive($record)&&!in_array($_GET['situacao']??'', ['inativos','todos'],true))$record=null;
  if(!$record){http_response_code(404);?><div class="empty">Registo não encontrado. <a class="action-link" href="<?=moduleUrl($module)?>">Voltar à listagem</a></div><?php }
  else{
   ?>
   <div class="page-heading"><div><h1><?=e($meta['singular'])?> · <?=e($record['id'])?></h1><p>Detalhes do registo</p><?php if(in_array($module,['clientes','processos','prazos'],true)&&currentUser()['perfil']==='Gestor'):?><p>Registado por: <?=e(recordOwnerLabel($record,$repo))?></p><?php endif?></div><div><a class="btn btn-light" href="<?=moduleUrl($module)?>"><?=iconSvg('chevron','button-svg back-svg')?> Voltar</a><?php if(can($module,'edit')&&canAccessRecord($module,$record,$repo,'edit')):?><a class="btn btn-primary" href="<?=moduleUrl($module,'editar',$id).(recordIsActive($record)?'':'&situacao=inativos')?>">Editar</a><?php endif?></div></div><div class="panel"><div class="detail-grid"><?php foreach($meta['fields'] as $key=>$def):if($module==='utilizadores'&&$key==='password')continue;?><div class="detail-item"><small><?=e($def[0])?></small><b><?=e(($module==='prazos'&&$key==='estado'?deadlineStatus($record):humanValue($key,$record[$key]??'',$repo))?:'—')?></b></div><?php endforeach?></div>
   <?php if($module==='vagas'){$candidates=array_filter(scopedRows('candidatos',$repo),fn($c)=>in_array($id,$c['vaga_ids']??[],true));?><h2>Candidatos associados (<?=count($candidates)?>)</h2><?php renderSimpleTable('candidatos',$repo,$entities,array_values($candidates));}?>
   <?php if(can($module,'edit')&&canAccessRecord($module,$record,$repo,'edit')):?><form method="post" action="<?=moduleUrl($module,'eliminar')?>" onsubmit="return confirm('Confirma esta alteração de situação?')" class="form-actions"><?php csrfInput();?><input type="hidden" name="id" value="<?=e($id)?>"><button class="btn btn-light"><?=recordIsActive($record)?'Inactivar registo':'Reactivar registo'?></button></form><?php endif?></div>
   <?php
  }
 }
}
pageEnd();

function renderSimpleTable(string $module,JsonRepository $repo,array $entities,array $rows,bool $actions=false):void{
 $meta=$entities[$module]??null;if(!$meta){echo '<p>Sem dados.</p>';return;}
 echo '<div class="table-wrap"><table><thead><tr><th>ID</th>';
 if(currentUser()['perfil']==='Gestor'&&in_array($module,['clientes','processos','prazos'],true))echo '<th>Registado por</th>';
 foreach($meta['fields'] as $key=>$def)if(!($module==='utilizadores'&&$key==='password')&&!in_array($key,['ativo','active'],true))echo '<th>'.e($def[0]).'</th>';
 echo '<th>Situação do registo</th>';if($actions)echo '<th>Acções</th>';echo '</tr></thead><tbody>';
 foreach($rows as $row){$active=recordIsActive($row);echo '<tr><td><span class="id-tag">'.e($row['id']).'</span></td>';
 if(currentUser()['perfil']==='Gestor'&&in_array($module,['clientes','processos','prazos'],true))echo '<td>'.e(recordOwnerLabel($row,$repo)).'</td>';
 foreach($meta['fields'] as $key=>$def){if(($module==='utilizadores'&&$key==='password')||in_array($key,['ativo','active'],true))continue;$value=$module==='prazos'&&$key==='estado'?deadlineStatus($row):humanValue($key,$row[$key]??'',$repo);$badge=$key==='estado';echo '<td>'.($badge?'<span class="badge '.(in_array($value,['Concluído','Concluído contratado','Concluído não contratado','Aberta','Dentro do prazo','Entregue no prazo'],true)?'green':(in_array($value,['Pendente','Em andamento','Próximo'],true)?'amber':'red')).'">':'').e($value).($badge?'</span>':'').'</td>';}
 echo '<td><span class="badge '.($active?'green':'red').'">'.($active?'Activo':'Inactivo').'</span></td>';
 if($actions){$inactiveQuery=$active?'':'&situacao=inativos';echo '<td><a class="action-link" href="'.e(moduleUrl($module,'detalhes',$row['id']).$inactiveQuery).'">Ver</a>';if(can($module,'edit')&&canAccessRecord($module,$row,$repo,'edit')){echo '<a class="action-link" href="'.e(moduleUrl($module,'editar',$row['id']).$inactiveQuery).'">Editar</a><form method="post" action="'.e(moduleUrl($module,'eliminar')).'" class="inline-form">';csrfInput();echo '<input type="hidden" name="id" value="'.e($row['id']).'"><button class="action-link" type="submit">'.($active?'Inactivar':'Reactivar').'</button></form>'; }echo '</td>';}
 echo '</tr>';}
 if(!$rows)echo '<tr><td colspan="12" class="empty">Não existem registos para apresentar com estes filtros.</td></tr>';echo '</tbody></table></div>';
}
